import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
/**
 * Where these seats are, on the ground's own seating chart.
 *
 * 🚨 The star is drawn only when the server resolved a point.
 *
 * Section numbering is not standardised between grounds, so there is no rule
 * that turns "114" into a position — only a tracing somebody did for this one
 * chart. When that section was never traced the chart still shows, because it
 * is useful on its own, but the listing's own words stand in place of a star.
 * A star in the wrong half of a ground is worse than none: a buyer believes a
 * picture over a sentence, and buys the wrong ticket.
 */
export default class SeatMapModal extends Modal {
  className() {
    return 'Modal--large ClassifiedsSeatMap-modal';
  }
  title() {
    return this.map()?.title || app.translator.trans('flarum-classifieds.forum.seatmap.title');
  }
  map() {
    return this.attrs.discussion.listingSeatMap?.() || null;
  }
  content() {
    const map = this.map();
    if (!map?.image) {
      return m("div", {
        className: "Modal-body"
      }, app.translator.trans('flarum-classifieds.forum.seatmap.unavailable'));
    }
    const point = map.point;
    const seats = this.attrs.discussion.listingSeatDisplay?.();
    const section = this.attrs.discussion.listingSection?.();
    return m("div", {
      className: "Modal-body ClassifiedsSeatMap"
    }, m("div", {
      className: "ClassifiedsSeatMap-stage"
    }, m("img", {
      className: "ClassifiedsSeatMap-image",
      src: map.image,
      alt: map.title
    }), point && m("span", {
      className: "ClassifiedsSeatMap-star",
      style: {
        left: point.x * 100 + '%',
        top: point.y * 100 + '%'
      },
      "aria-label": app.translator.trans('flarum-classifieds.forum.seatmap.marker', {
        section
      }, true)
    }, m("i", {
      className: "fas fa-star",
      "aria-hidden": "true"
    }))), m("p", {
      className: "ClassifiedsSeatMap-caption"
    }, seats, !point && section && m("span", {
      className: "ClassifiedsSeatMap-untraced"
    }, app.translator.trans('flarum-classifieds.forum.seatmap.not_marked', {
      section
    }))));
  }
}
flarum.reg.add('ernestdefoe-classifieds', 'forum/components/SeatMapModal', SeatMapModal);